mod ffi {
    struct PacketResult {
        success: bool,
        bytes_processed: u32,
        error_code: u32,
    }

    unsafe extern "C++" {
        include!("packet_processor.h");

        type PacketProcessor;

        fn create_processor(config: &CxxString) -> UniquePtr<PacketProcessor>;
        fn process_payload(self: &PacketProcessor, data: &[u8]) -> PacketResult;
    }
}

// Safe Idiomatic Wrapper for Production Services
pub struct SafePacketProcessor {
    inner: cxx::UniquePtr<ffi::PacketProcessor>,
}

// Enforce Thread Safety if C++ implementation is thread-safe
unsafe impl Send for SafePacketProcessor {}
unsafe impl Sync for SafePacketProcessor {}

impl SafePacketProcessor {
    pub fn new(config_json: &str) -> Result<Self, String> {
        cxx::let_cxx_string!(config = config_json);
        let processor = ffi::create_processor(&config);
        if processor.is_null() {
            Err("Failed to initialize C++ PacketProcessor instance".into())
        } else {
            Ok(Self { inner: processor })
        }
    }

    pub fn process(&self, payload: &[u8]) -> Result<u32, u32> {
        let res = self.inner.process_payload(payload);
        if res.success {
            Ok(res.bytes_processed)
        } else {
            Err(res.error_code)
        }
    }
}
```

